-- IONDU: esquema relacional generado desde SQLAlchemy.
-- BORRADOR: revisar antes de utilizar en una instalaci?n.
-- Requiere que exista auth.users en Supabase.
-- No incluye funciones, triggers, pol?ticas RLS ni datos iniciales.

CREATE TABLE empresa (
	id_empresa INTEGER GENERATED BY DEFAULT AS IDENTITY,
	razon_social VARCHAR(255) NOT NULL,
	nombre_comercial VARCHAR(255),
	ruc VARCHAR(13) NOT NULL,
	actividad_economica VARCHAR(255),
	direccion TEXT,
	correo_electronico VARCHAR(150) NOT NULL,
	datos_facturacion_electronica JSONB,
	certificado_p12_cifrado TEXT,
	certificado_password_cifrada TEXT,
	certificado_fecha_vencimiento DATE,
	fecha_creacion TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	CONSTRAINT empresa_pkey PRIMARY KEY (id_empresa),
	CONSTRAINT empresa_ruc_key UNIQUE (ruc),
	CONSTRAINT empresa_ruc_formato CHECK (ruc ~ '^[0-9]{13}$'),
	CONSTRAINT empresa_certificado_par_check CHECK (
            (
                certificado_p12_cifrado IS NULL
                AND certificado_password_cifrada IS NULL
            )
            OR
            (
                certificado_p12_cifrado IS NOT NULL
                AND certificado_password_cifrada IS NOT NULL
            )
            )
);

CREATE TABLE rol (
	id_rol SERIAL NOT NULL,
	nombre VARCHAR(50) NOT NULL,
	descripcion VARCHAR(255),
	CONSTRAINT rol_pkey PRIMARY KEY (id_rol),
	CONSTRAINT rol_nombre_key UNIQUE (nombre)
);

CREATE TABLE categoria_gasto (
	id_categoria_gasto INTEGER GENERATED BY DEFAULT AS IDENTITY,
	id_empresa INTEGER NOT NULL,
	nombre VARCHAR(100) NOT NULL,
	origen VARCHAR(50) DEFAULT 'PREDEFINIDA' NOT NULL,
	descripcion VARCHAR(255),
	CONSTRAINT categoria_gasto_pkey PRIMARY KEY (id_categoria_gasto),
	CONSTRAINT categoria_gasto_empresa_id_uq UNIQUE (id_empresa, id_categoria_gasto),
	CONSTRAINT categoria_gasto_nombre_uq UNIQUE (id_empresa, nombre),
	CONSTRAINT categoria_gasto_id_empresa_fkey FOREIGN KEY(id_empresa) REFERENCES empresa (id_empresa) ON DELETE CASCADE
);

CREATE TABLE categoria_producto (
	id_categoria_producto INTEGER GENERATED BY DEFAULT AS IDENTITY,
	id_empresa INTEGER NOT NULL,
	nombre VARCHAR(100) NOT NULL,
	descripcion VARCHAR(255),
	CONSTRAINT categoria_producto_pkey PRIMARY KEY (id_categoria_producto),
	CONSTRAINT categoria_producto_empresa_id_uq UNIQUE (id_empresa, id_categoria_producto),
	CONSTRAINT categoria_producto_nombre_uq UNIQUE (id_empresa, nombre),
	CONSTRAINT categoria_producto_id_empresa_fkey FOREIGN KEY(id_empresa) REFERENCES empresa (id_empresa) ON DELETE CASCADE
);

CREATE TABLE cliente (
	id_cliente INTEGER GENERATED BY DEFAULT AS IDENTITY,
	id_empresa INTEGER NOT NULL,
	tipo_identificacion VARCHAR(20) NOT NULL,
	identificacion VARCHAR(20) NOT NULL,
	nombre_razon_social VARCHAR(255) NOT NULL,
	direccion TEXT,
	telefono VARCHAR(20),
	correo_electronico VARCHAR(150),
	CONSTRAINT cliente_pkey PRIMARY KEY (id_cliente),
	CONSTRAINT cliente_empresa_id_uq UNIQUE (id_empresa, id_cliente),
	CONSTRAINT cliente_identificacion_empresa_uq UNIQUE (id_empresa, tipo_identificacion, identificacion),
	CONSTRAINT cliente_id_empresa_fkey FOREIGN KEY(id_empresa) REFERENCES empresa (id_empresa) ON DELETE CASCADE
);

CREATE INDEX idx_cliente_empresa ON cliente (id_empresa);

CREATE TABLE consumo_tokens (
	id_consumo_tokens INTEGER GENERATED BY DEFAULT AS IDENTITY,
	id_empresa INTEGER NOT NULL,
	modelo_ia VARCHAR(50) NOT NULL,
	tokens_prompt INTEGER DEFAULT 0 NOT NULL,
	tokens_completado INTEGER DEFAULT 0 NOT NULL,
	costo_estimado NUMERIC(12, 6) DEFAULT 0 NOT NULL,
	fecha TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	CONSTRAINT consumo_tokens_pkey PRIMARY KEY (id_consumo_tokens),
	CONSTRAINT consumo_tokens_tokens_prompt_check CHECK (tokens_prompt >= 0),
	CONSTRAINT consumo_tokens_tokens_completado_check CHECK (tokens_completado >= 0),
	CONSTRAINT consumo_tokens_costo_estimado_check CHECK (costo_estimado >= 0),
	CONSTRAINT consumo_tokens_id_empresa_fkey FOREIGN KEY(id_empresa) REFERENCES empresa (id_empresa) ON DELETE CASCADE
);

CREATE INDEX idx_consumo_tokens_empresa_fecha ON consumo_tokens (id_empresa, fecha DESC);

CREATE TABLE dashboard_financiero (
	id_dashboard INTEGER GENERATED BY DEFAULT AS IDENTITY,
	id_empresa INTEGER NOT NULL,
	periodo VARCHAR(7) NOT NULL,
	ingresos_totales NUMERIC(12, 2) DEFAULT 0 NOT NULL,
	gastos_totales NUMERIC(12, 2) DEFAULT 0 NOT NULL,
	utilidad_neta NUMERIC(12, 2) DEFAULT 0 NOT NULL,
	ventas_registradas INTEGER DEFAULT 0 NOT NULL,
	gastos_por_categoria JSONB,
	estado_inventario JSONB,
	productos_stock_bajo INTEGER DEFAULT 0 NOT NULL,
	fecha_calculo TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	CONSTRAINT dashboard_financiero_pkey PRIMARY KEY (id_dashboard),
	CONSTRAINT dashboard_financiero_productos_stock_bajo_check CHECK (productos_stock_bajo >= 0),
	CONSTRAINT dashboard_financiero_ventas_registradas_check CHECK (ventas_registradas >= 0),
	CONSTRAINT dashboard_periodo_formato_ck CHECK (periodo ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
	CONSTRAINT dashboard_empresa_periodo_uq UNIQUE (id_empresa, periodo),
	CONSTRAINT dashboard_financiero_id_empresa_fkey FOREIGN KEY(id_empresa) REFERENCES empresa (id_empresa) ON DELETE CASCADE
);

CREATE TABLE proveedor (
	id_proveedor INTEGER GENERATED BY DEFAULT AS IDENTITY,
	id_empresa INTEGER NOT NULL,
	ruc_identificacion VARCHAR(20) NOT NULL,
	razon_social VARCHAR(255) NOT NULL,
	telefono VARCHAR(20),
	correo_electronico VARCHAR(150),
	direccion TEXT,
	CONSTRAINT proveedor_pkey PRIMARY KEY (id_proveedor),
	CONSTRAINT proveedor_empresa_id_uq UNIQUE (id_empresa, id_proveedor),
	CONSTRAINT proveedor_identificacion_empresa_uq UNIQUE (id_empresa, ruc_identificacion),
	CONSTRAINT proveedor_id_empresa_fkey FOREIGN KEY(id_empresa) REFERENCES empresa (id_empresa) ON DELETE CASCADE
);

CREATE INDEX idx_proveedor_empresa ON proveedor (id_empresa);

CREATE TABLE recomendacion (
	id_recomendacion INTEGER GENERATED BY DEFAULT AS IDENTITY,
	id_empresa INTEGER NOT NULL,
	tipo VARCHAR(50) NOT NULL,
	descripcion TEXT NOT NULL,
	datos_utilizados JSONB,
	estado VARCHAR(20) DEFAULT 'ACTIVA' NOT NULL,
	fecha TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	CONSTRAINT recomendacion_pkey PRIMARY KEY (id_recomendacion),
	CONSTRAINT recomendacion_id_empresa_fkey FOREIGN KEY(id_empresa) REFERENCES empresa (id_empresa) ON DELETE CASCADE
);

CREATE INDEX idx_recomendacion_empresa_fecha ON recomendacion (id_empresa, fecha DESC);

CREATE TABLE usuario_empresa (
	id_usuario UUID NOT NULL,
	id_empresa INTEGER NOT NULL,
	id_rol INTEGER NOT NULL,
	estado VARCHAR(20) DEFAULT 'ACTIVO' NOT NULL,
	nombre_visible VARCHAR(150),
	fecha_creacion TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	CONSTRAINT usuario_empresa_pkey PRIMARY KEY (id_usuario, id_empresa),
	CONSTRAINT usuario_empresa_id_usuario_fkey FOREIGN KEY(id_usuario) REFERENCES auth.users (id) ON DELETE CASCADE,
	CONSTRAINT usuario_empresa_usuario_empresa_estado_ck_check CHECK (estado IN ('ACTIVO', 'INACTIVO', 'INVITADO')),
	CONSTRAINT usuario_empresa_id_empresa_fkey FOREIGN KEY(id_empresa) REFERENCES empresa (id_empresa) ON DELETE CASCADE,
	CONSTRAINT usuario_empresa_id_rol_fkey FOREIGN KEY(id_rol) REFERENCES rol (id_rol) ON DELETE RESTRICT
);

CREATE INDEX idx_usuario_empresa_empresa ON usuario_empresa (id_empresa);

CREATE TABLE secuencia_comprobante (
	id_secuencia INTEGER GENERATED BY DEFAULT AS IDENTITY,
	id_empresa INTEGER NOT NULL,
	establecimiento VARCHAR(3) NOT NULL,
	punto_emision VARCHAR(3) NOT NULL,
	tipo_comprobante VARCHAR(2) NOT NULL,
	ultimo_secuencial BIGINT DEFAULT 0 NOT NULL,
	CONSTRAINT secuencia_comprobante_pkey PRIMARY KEY (id_secuencia),
	CONSTRAINT secuencia_comprobante_establecimiento_ck CHECK (establecimiento ~ '^[0-9]{3}$'),
	CONSTRAINT secuencia_comprobante_punto_emision_ck CHECK (punto_emision ~ '^[0-9]{3}$'),
	CONSTRAINT secuencia_comprobante_tipo_ck CHECK (tipo_comprobante ~ '^[0-9]{2}$'),
	CONSTRAINT secuencia_comprobante_ultimo_ck CHECK (ultimo_secuencial BETWEEN 0 AND 999999999),
	CONSTRAINT secuencia_comprobante_configuracion_uq UNIQUE (id_empresa, establecimiento, punto_emision, tipo_comprobante),
	CONSTRAINT secuencia_comprobante_id_empresa_fkey FOREIGN KEY(id_empresa) REFERENCES empresa (id_empresa) ON DELETE CASCADE
);

CREATE TABLE accion_ia (
	id_accion_ia INTEGER GENERATED BY DEFAULT AS IDENTITY,
	id_empresa INTEGER NOT NULL,
	id_usuario UUID,
	tipo_accion VARCHAR(50) NOT NULL,
	instruccion_recibida TEXT NOT NULL,
	payload_json JSONB,
	estado VARCHAR(20) DEFAULT 'PENDIENTE' NOT NULL,
	fecha TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	CONSTRAINT accion_ia_pkey PRIMARY KEY (id_accion_ia),
	CONSTRAINT accion_ia_usuario_empresa_fk FOREIGN KEY(id_usuario, id_empresa) REFERENCES usuario_empresa (id_usuario, id_empresa) ON DELETE SET NULL (id_usuario),
	CONSTRAINT accion_ia_id_empresa_fkey FOREIGN KEY(id_empresa) REFERENCES empresa (id_empresa) ON DELETE CASCADE
);

CREATE INDEX idx_accion_ia_empresa_fecha ON accion_ia (id_empresa, fecha DESC);

CREATE TABLE gasto (
	id_gasto INTEGER GENERATED BY DEFAULT AS IDENTITY,
	id_empresa INTEGER NOT NULL,
	id_categoria_gasto INTEGER NOT NULL,
	id_usuario UUID NOT NULL,
	id_proveedor INTEGER,
	monto NUMERIC(12, 2) NOT NULL,
	fecha TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	numero_comprobante VARCHAR(50),
	message_id_correo VARCHAR(998),
	clave_acceso VARCHAR(49),
	concepto TEXT NOT NULL,
	metodo_pago VARCHAR(50) NOT NULL,
	estado VARCHAR(20) DEFAULT 'CONFIRMADO' NOT NULL,
	CONSTRAINT gasto_pkey PRIMARY KEY (id_gasto),
	CONSTRAINT gasto_empresa_message_id_correo_uq UNIQUE (id_empresa, message_id_correo),
	CONSTRAINT gasto_empresa_clave_acceso_uq UNIQUE (id_empresa, clave_acceso),
	CONSTRAINT gasto_monto_check CHECK (monto >= 0),
	CONSTRAINT gasto_categoria_empresa_fk FOREIGN KEY(id_empresa, id_categoria_gasto) REFERENCES categoria_gasto (id_empresa, id_categoria_gasto) ON DELETE RESTRICT,
	CONSTRAINT gasto_proveedor_empresa_fk FOREIGN KEY(id_empresa, id_proveedor) REFERENCES proveedor (id_empresa, id_proveedor) ON DELETE SET NULL (id_proveedor),
	CONSTRAINT gasto_usuario_empresa_fk FOREIGN KEY(id_usuario, id_empresa) REFERENCES usuario_empresa (id_usuario, id_empresa) ON DELETE RESTRICT,
	CONSTRAINT gasto_id_empresa_fkey FOREIGN KEY(id_empresa) REFERENCES empresa (id_empresa) ON DELETE CASCADE
);

CREATE INDEX idx_gasto_empresa_fecha ON gasto (id_empresa, fecha DESC);

CREATE INDEX idx_gasto_usuario ON gasto (id_usuario);

CREATE INDEX idx_gasto_proveedor ON gasto (id_proveedor);

CREATE TABLE producto (
	id_producto INTEGER GENERATED BY DEFAULT AS IDENTITY,
	id_empresa INTEGER NOT NULL,
	id_categoria_producto INTEGER NOT NULL,
	codigo_principal VARCHAR(50) NOT NULL,
	nombre VARCHAR(150) NOT NULL,
	descripcion TEXT,
	precio_compra NUMERIC(12, 4) DEFAULT 0 NOT NULL,
	precio_venta NUMERIC(12, 4) DEFAULT 0 NOT NULL,
	stock_actual NUMERIC(12, 4) DEFAULT 0 NOT NULL,
	stock_minimo NUMERIC(12, 4),
	unidad_medida VARCHAR(20) DEFAULT 'UNIDAD' NOT NULL,
	tipo VARCHAR(20) DEFAULT 'VENTA' NOT NULL,
	aplica_iva BOOLEAN DEFAULT true NOT NULL,
	codigo_porcentaje_iva VARCHAR(2) DEFAULT '4' NOT NULL,
	activo BOOLEAN DEFAULT true NOT NULL,
	CONSTRAINT producto_pkey PRIMARY KEY (id_producto),
	CONSTRAINT producto_empresa_id_uq UNIQUE (id_empresa, id_producto),
	CONSTRAINT producto_categoria_empresa_fk FOREIGN KEY(id_empresa, id_categoria_producto) REFERENCES categoria_producto (id_empresa, id_categoria_producto) ON DELETE RESTRICT,
	CONSTRAINT producto_precio_compra_check CHECK (precio_compra >= 0),
	CONSTRAINT producto_precio_venta_check CHECK (precio_venta >= 0),
	CONSTRAINT producto_stock_actual_check CHECK (stock_actual >= 0),
	CONSTRAINT producto_stock_minimo_check CHECK (stock_minimo IS NULL OR stock_minimo >= 0),
	CONSTRAINT producto_codigo_porcentaje_iva_check CHECK (codigo_porcentaje_iva IN ('0', '4', '5', '6', '7')),
	CONSTRAINT producto_id_empresa_fkey FOREIGN KEY(id_empresa) REFERENCES empresa (id_empresa) ON DELETE CASCADE
);

CREATE INDEX idx_producto_empresa ON producto (id_empresa);

CREATE UNIQUE INDEX producto_codigo_empresa_lower_uq ON producto (id_empresa, lower(codigo_principal));

CREATE INDEX idx_producto_categoria ON producto (id_categoria_producto);

CREATE TABLE venta (
	id_venta INTEGER GENERATED BY DEFAULT AS IDENTITY,
	id_empresa INTEGER NOT NULL,
	id_usuario UUID NOT NULL,
	id_cliente INTEGER,
	fecha TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	subtotal NUMERIC(12, 2) NOT NULL,
	iva NUMERIC(12, 2) NOT NULL,
	monto_total NUMERIC(12, 2) NOT NULL,
	tipo_origen VARCHAR(30) NOT NULL,
	metodo_pago VARCHAR(50) NOT NULL,
	observacion VARCHAR(255),
	estado VARCHAR(20) DEFAULT 'COMPLETADA' NOT NULL,
	CONSTRAINT venta_pkey PRIMARY KEY (id_venta),
	CONSTRAINT venta_empresa_id_uq UNIQUE (id_empresa, id_venta),
	CONSTRAINT venta_iva_check CHECK (iva >= 0),
	CONSTRAINT venta_monto_total_check CHECK (monto_total >= 0),
	CONSTRAINT venta_subtotal_check CHECK (subtotal >= 0),
	CONSTRAINT venta_cliente_empresa_fk FOREIGN KEY(id_empresa, id_cliente) REFERENCES cliente (id_empresa, id_cliente) ON DELETE SET NULL (id_cliente),
	CONSTRAINT venta_usuario_empresa_fk FOREIGN KEY(id_usuario, id_empresa) REFERENCES usuario_empresa (id_usuario, id_empresa) ON DELETE RESTRICT,
	CONSTRAINT venta_id_empresa_fkey FOREIGN KEY(id_empresa) REFERENCES empresa (id_empresa) ON DELETE CASCADE
);

CREATE INDEX idx_venta_usuario_empresa ON venta (id_usuario, id_empresa);

CREATE INDEX idx_venta_empresa_fecha_id ON venta (id_empresa, fecha DESC, id_venta);

CREATE INDEX idx_venta_empresa_cliente ON venta (id_empresa, id_cliente);

CREATE TABLE detalle_venta (
	id_detalle_venta INTEGER GENERATED BY DEFAULT AS IDENTITY,
	id_empresa INTEGER NOT NULL,
	id_venta INTEGER NOT NULL,
	id_producto INTEGER,
	descripcion_libre VARCHAR(255),
	cantidad NUMERIC(12, 4) NOT NULL,
	precio_unitario NUMERIC(12, 4) NOT NULL,
	descuento NUMERIC(12, 2) DEFAULT 0 NOT NULL,
	codigo_porcentaje_iva VARCHAR(2) NOT NULL,
	subtotal NUMERIC(12, 2) NOT NULL,
	CONSTRAINT detalle_venta_pkey PRIMARY KEY (id_detalle_venta),
	CONSTRAINT detalle_venta_empresa_venta_fk FOREIGN KEY(id_empresa, id_venta) REFERENCES venta (id_empresa, id_venta) ON DELETE CASCADE,
	CONSTRAINT detalle_venta_empresa_producto_fk FOREIGN KEY(id_empresa, id_producto) REFERENCES producto (id_empresa, id_producto) ON DELETE SET NULL (id_producto),
	CONSTRAINT detalle_venta_cantidad_check CHECK (cantidad > 0),
	CONSTRAINT detalle_venta_descuento_check CHECK (descuento >= 0),
	CONSTRAINT detalle_venta_precio_unitario_check CHECK (precio_unitario >= 0),
	CONSTRAINT detalle_venta_producto_o_descripcion_ck CHECK (id_producto IS NOT NULL OR descripcion_libre IS NOT NULL),
	CONSTRAINT detalle_venta_codigo_iva_check CHECK (codigo_porcentaje_iva IN ('0', '4', '5', '6', '7')),
	CONSTRAINT detalle_venta_subtotal_check CHECK (subtotal >= 0)
);

CREATE INDEX idx_detalle_venta_empresa_venta ON detalle_venta (id_empresa, id_venta, id_detalle_venta);

CREATE INDEX idx_detalle_venta_empresa_producto ON detalle_venta (id_empresa, id_producto);

CREATE TABLE factura (
	id_factura INTEGER GENERATED BY DEFAULT AS IDENTITY,
	id_empresa INTEGER NOT NULL,
	id_venta INTEGER NOT NULL,
	numero_comprobante VARCHAR(17) NOT NULL,
	clave_acceso VARCHAR(49),
	estado_autorizacion VARCHAR(30) NOT NULL,
	numero_autorizacion VARCHAR(49),
	fecha_autorizacion TIMESTAMP WITH TIME ZONE,
	mensajes_sri JSONB DEFAULT '[]'::jsonb NOT NULL,
	intentos_envio INTEGER DEFAULT 0 NOT NULL,
	subtotal NUMERIC(12, 2) NOT NULL,
	impuestos NUMERIC(12, 2) NOT NULL,
	total NUMERIC(12, 2) NOT NULL,
	fecha_emision TIMESTAMP WITH TIME ZONE NOT NULL,
	xml_firmado TEXT,
	xml_autorizado TEXT,
	pdf_ride_path VARCHAR(255),
	CONSTRAINT factura_pkey PRIMARY KEY (id_factura),
	CONSTRAINT factura_impuestos_check CHECK (impuestos >= 0),
	CONSTRAINT factura_numero_formato_ck CHECK (numero_comprobante ~ '^[0-9]{3}-[0-9]{3}-[0-9]{9}$'),
	CONSTRAINT factura_subtotal_check CHECK (subtotal >= 0),
	CONSTRAINT factura_total_check CHECK (total >= 0),
	CONSTRAINT factura_intentos_envio_check CHECK (intentos_envio >= 0),
	CONSTRAINT factura_estado_autorizacion_check CHECK (estado_autorizacion IN ('autorizada', 'rechazada', 'por_enviar', 'por_autorizar')),
	CONSTRAINT factura_id_venta_key UNIQUE (id_venta),
	CONSTRAINT factura_empresa_numero_uq UNIQUE (id_empresa, numero_comprobante),
	CONSTRAINT factura_clave_acceso_key UNIQUE (clave_acceso),
	CONSTRAINT factura_venta_empresa_fk FOREIGN KEY(id_empresa, id_venta) REFERENCES venta (id_empresa, id_venta) ON DELETE CASCADE,
	CONSTRAINT factura_id_empresa_fkey FOREIGN KEY(id_empresa) REFERENCES empresa (id_empresa) ON DELETE CASCADE
);

CREATE INDEX idx_factura_empresa_fecha ON factura (id_empresa, fecha_emision DESC);

CREATE TABLE movimiento_inventario (
	id_movimiento INTEGER GENERATED BY DEFAULT AS IDENTITY,
	id_empresa INTEGER NOT NULL,
	id_producto INTEGER NOT NULL,
	id_usuario UUID NOT NULL,
	tipo_movimiento VARCHAR(30) NOT NULL,
	cantidad NUMERIC(12, 4) NOT NULL,
	fecha TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	motivo VARCHAR,
	CONSTRAINT movimiento_inventario_pkey PRIMARY KEY (id_movimiento),
	CONSTRAINT movimiento_inventario_empresa_producto_fkey FOREIGN KEY(id_empresa, id_producto) REFERENCES producto (id_empresa, id_producto) ON DELETE RESTRICT,
	CONSTRAINT movimiento_inventario_usuario_empresa_fkey FOREIGN KEY(id_usuario, id_empresa) REFERENCES usuario_empresa (id_usuario, id_empresa) ON DELETE RESTRICT,
	CONSTRAINT movimiento_inventario_cantidad_check CHECK (cantidad > 0)
);

CREATE INDEX idx_movimiento_empresa ON movimiento_inventario (id_empresa);

CREATE INDEX idx_movimiento_usuario ON movimiento_inventario (id_usuario);

CREATE INDEX idx_movimiento_producto_fecha ON movimiento_inventario (id_producto, fecha DESC);
